import heapq

def dijkstra(graph, source):
    """
    Returns (distances, prev) where distances maps each node to its shortest
    distance from source, and prev maps each node to its predecessor on the
    shortest path.

    graph: dict mapping each node to a dict {neighbor: weight, ...}
    source: starting node
    """
    distances = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    distances[source] = 0
    pq = [(0, source)]

    while pq:
        dist, u = heapq.heappop(pq)
        if dist > distances[u]:
            continue
        for v, weight in graph[u].items():
            if weight < 0:
                raise ValueError("Dijkstra does not support negative edge weights")
            new_dist = dist + weight
            if new_dist < distances[v]:
                distances[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    return distances, prev
